-- Second batch of jobs: customer support, marketing, QA
insert into public.jobs (id, data, active, found_on) values ('upwind-support-student', $j${"company": "Upwind Security", "role": "Technical Support Engineer - Student (מהנדס/ת תמיכה טכנית, משרת סטודנט)", "location": "רמת גן (מנחם בגין 13), עבודה מהמשרד", "url": "https://www.comeet.com/jobs/upwind/49.004/technical-support-engineer--student/93.57F", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פלטפורמת אבטחת ענן שמזהה ומתעדפת סיכונים על בסיס נתוני זמן ריצה. הלקוחות הם ארגונים שמריצים תשתיות בענן וצוותי האבטחה שלהם.", "about": "לפי המודעה, אחת מחברות הסייבר שצומחות מהר. חברה פרטית ישראלית שהוקמה ב-2022 וגייסה סבבי הון גדולים (מידע כללי, כדאי לאמת).", "requires": ["סטודנט/ית לתואר בהנדסה, מדעי המחשב, סייבר או תחום קרוב (חובה)", "לפחות שנת לימודים מלאה אחת עד סיום התואר (חובה)", "אנגלית שוטפת בכתב ובעל פה (חובה)", "זמינות לעבודה אינטנסיבית כולל משמרות לילה וסופי שבוע (חובה)", "יתרון: היכרות עם Linux, רשתות בסיסיות, SQL או סביבות ענן"], "comp": "במודעה לא צוינו שכר או תנאים. צוין שזו משרת כניסה עם הכשרה מעשית, חניכה ואפשרות להתפתח לתפקיד מהנדס/ת תמיכה מלא.", "ask": ["כמה משמרות לילה וסופי שבוע נדרשות בחודש, ואיך משלבים אותן עם מערכת הלימודים?", "איך נראית ההכשרה בחודשים הראשונים ומי מלווה את הסטודנט/ית?", "מה המסלול ולוח הזמנים המקובל למעבר לתפקיד תמיכה מלא?"], "function": "שירות ותמיכת לקוחות", "regions": ["מרכז"], "mode": "משרד", "car": "unknown", "minYears": 0, "level": "junior", "sector": "תוכנה ואינטרנט", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('jfrog-developer-support', $j${"company": "JFrog", "role": "Developer Support Engineer", "location": "נתניה, היברידי (המודעה מציינת משרה היברידית שבסיסה במשרד נתניה)", "url": "https://join.jfrog.com/job/8264438-developer-support-engineer/?gh_jid=8264438", "applyHow": "מגישים מועמדות בכפתור ההגשה ובטופס שבעמוד המשרה באתר הקריירה של JFrog.", "sells": "פלטפורמת DevSecOps לניהול, האצה ואבטחה של אספקת תוכנה מהקוד ועד הייצור. הלקוחות הם ארגוני פיתוח, ולפי המודעה אלפי לקוחות ובהם רוב חברות Fortune 100.", "about": "חברה ישראלית-אמריקאית שנסחרת בנאסד\"ק, עם מרכזי פיתוח בנתניה ובתל אביב (מידע כללי, כדאי לאמת).", "requires": ["תואר B.Sc. או שווה ערך במדעי המחשב, הנדסת מחשבים או תחום טכני קרוב", "שנתיים ומעלה ניסיון מעשי בתפקיד טכני (תמיכה Tier 3, NOC, Production Engineer או DevOps/SRE זוטר)", "ניסיון מעמיק ב-Linux, כולל Bash וניתוח לוגים ואיתור שורש תקלה", "יכולת לקרוא ולדבג קוד ב-Java או בשפה מקומפלת אחרת", "אנגלית מצוינת בכתב ובעל פה"], "comp": "במודעה לא צוינו שכר או תנאים. צוינה דרישה לזמינות לשעות גמישות ולסופי שבוע בעת הצורך.", "ask": ["באיזו תדירות נדרשת עבודה בסופי שבוע או בשעות חריגות, ואיך היא מתוגמלת?", "כמה ימים בשבוע עובדים מהמשרד בנתניה?", "מה היחס בין טיפול בפניות לקוחות לבין כתיבת סקריפטים וכלי אוטומציה?"], "function": "שירות ותמיכת לקוחות", "regions": ["שרון"], "mode": "היברידי", "car": "unknown", "minYears": 2, "level": "mid", "sector": "תוכנה ואינטרנט", "english": "fluent", "needsDegree": true, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('kaltura-tech-support', $j${"company": "Kaltura", "role": "Technical Support Engineer", "location": "בני ברק, היברידי", "url": "https://www.comeet.com/jobs/kaltura/E2.00D/technical-support-engineer/FE.277", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פלטפורמת תוכנה (SaaS) לווידאו ולחוויות דיגיטליות מבוססות AI, כולל פתרון IPTV שבו עוסק התפקיד. הלקוחות הם ארגונים עסקיים, חברות אנטרפרייז, מוסדות לימוד וחברות מדיה.", "about": "לפי המודעה: נוסדה ב-2006, נסחרת בבורסת ניו יורק (KLTR), מעל 600 עובדים ומעל 1,000 ארגונים לקוחות.", "requires": ["תואר אקדמי במדעי המחשב, הנדסת אלקטרוניקה או תחום תקשורת (מופיע תחת 'מה אנחנו מחפשים באופן אידיאלי')", "3 שנים ומעלה בתפקיד דומה, כולל קשר ישיר עם לקוחות", "ניסיון קודם בתמיכה בתוכנת SaaS", "שנתיים ומעלה ניסיון מעשי ב-API ושנתיים ומעלה ב-SQL", "היכרות עם כלי Back Office כגון Jira"], "comp": "שכר לא צוין. ההטבות שצוינו במודעה: עבודה היברידית וגמישה, ביטוח בריאות פרטי מורחב (כולל בריאות הנפש), תוכניות פיתוח אישי ומקצועי וסופי שבוע ארוכים כלל-חברתיים מדי פעם.", "ask": ["הצוות פרוס בשלוש יבשות: האם יש משמרות או כוננויות מחוץ לשעות העבודה בישראל?", "כמה ימים בשבוע נדרשים במשרד בבני ברק?", "אילו סוגי תקלות אמורים להיפתר עצמאית ומה מועבר ל-Tier 4 ולפיתוח?"], "function": "שירות ותמיכת לקוחות", "regions": ["מרכז"], "mode": "היברידי", "car": "unknown", "minYears": 3, "level": "mid", "sector": "תוכנה ואינטרנט", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('drsrada-service-desk-beersheva', $j${"company": "DRS RADA Technologies", "role": "Service Desk Specialist (מומחה/ית תמיכת IT באתר)", "location": "באר שבע (פארק ההייטק גב-ים נגב), עבודה מהמשרד", "url": "https://www.comeet.com/jobs/rada/73.009/service-desk-specialist/0B.374", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "מערכות מכ\"ם טקטיות להגנה אקטיבית, לנטרול רחפנים, להגנה על תשתיות קריטיות ולאבטחת גבולות. הלקוחות הם צבאות וגופי ביטחון.", "about": "חברה ביטחונית ישראלית שהיא חלק מקבוצת Leonardo DRS האמריקאית, עם אתרים בנתניה, בבית שאן וביקנעם (מידע כללי, כדאי לאמת). לפי המודעה, התפקיד הוא מוקד ה-IT הראשי באתר חדש של החברה.", "requires": ["3 שנים ומעלה ניסיון בתמיכת IT או בניהול מערכות", "ידע חזק ב-Windows, Microsoft 365, Active Directory, רשתות ותמיכה בתחנות קצה", "יכולת איתור תקלות ושירותיות גבוהה", "יכולת לעבוד עצמאית ולקחת אחריות מלאה על תפעול ה-IT באתר", "עברית ואנגלית ברמה גבוהה בכתב ובעל פה"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["כמה עובדים יש באתר בבאר שבע ומה קצב הגידול הצפוי?", "איזו תמיכה מתקבלת מצוות ה-IT המרכזי ומה נשאר באחריות מקומית מלאה?", "האם נדרשים סיווג ביטחוני או זמינות מחוץ לשעות העבודה?"], "function": "שירות ותמיכת לקוחות", "regions": ["דרום"], "mode": "משרד", "car": "unknown", "minYears": 3, "level": "mid", "sector": "אבטחה ומיגון", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('abra-junior-marketing-cloud', $j${"company": "abra", "role": "Junior Marketing Coordinator - Cloud (רכז/ת שיווק זוטר/ה, חטיבת הענן)", "location": "אזור המרכז (העיר לא צוינה במודעה), עבודה מהמשרד, משרה חלקית לפי רישום המשרה", "url": "https://www.comeet.com/jobs/abra_rnd/15.007/junior-marketing-coordinator--cloud/7D.470", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "שירותי IT, ענן, AI ופתרונות טכנולוגיה מתקדמים. הלקוחות הם ארגונים ועסקים (שיווק B2B).", "about": "קבוצת שירותי טכנולוגיה ישראלית גדולה שנסחרת בבורסה בתל אביב (מידע כללי, כדאי לאמת). לפי המודעה, התפקיד כפוף ישירות לסמנכ\"ל/ית השיווק של חטיבת הענן.", "requires": ["תואר ראשון בשיווק, מנהל עסקים או תקשורת (חובה)", "ניסיון מעשי בשימוש בכלי AI בתהליכי שיווק", "עברית ברמה גבוהה בכתב ובעל פה ואנגלית ברמה גבוהה, והיכרות עם רשתות חברתיות ובעיקר LinkedIn", "ניסיון מעשי בתכנון, תיאום וניהול וובינרים", "ניסיון מעשי בתיאום והפקה של אירועים וכנסים מקצועיים, כולל אירועי ערב מדי פעם"], "comp": "במודעה לא צוינו שכר או תנאים. ברישום המשרה מצוין היקף משרה חלקי.", "ask": ["מה היקף המשרה בפועל (ימים ושעות) והיכן נמצא המשרד?", "באיזו תדירות יש אירועי ערב ואיך הם מתוגמלים?", "מה החלוקה בין יצירת תוכן, הפקת אירועים וניתוח קמפיינים?"], "function": "שיווק", "regions": ["מרכז"], "mode": "משרד", "car": "unknown", "minYears": 0, "level": "junior", "sector": "תוכנה ואינטרנט", "english": "good", "needsDegree": true, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('alma-social-campaign-caesarea', $j${"company": "Alma Lasers", "role": "Social Media & Campaign Specialist", "location": "קיסריה (אזור התעשייה, רחוב החרש 18), עבודה מהמשרד", "url": "https://www.comeet.com/jobs/almalasers/67.006/social-media--campaign-specialist/DA.472", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "מכשור רפואי-אסתטי מבוסס אנרגיה (לייזרים ועוד), לצד מוצרי הזרקה, אבחון וטיפוח עור. הלקוחות הם קליניקות אסתטיות ורופאים ביותר מ-100 מדינות.", "about": "לפי המודעה: חברה בקבוצת Sisram Medical, עם מעל 25 שנות ניסיון ומטה בקיסריה. Sisram נסחרת בבורסת הונג קונג ונשלטת בידי קבוצת Fosun (מידע כללי, כדאי לאמת).", "requires": ["3 שנים ומעלה ניסיון מעשי ביצירת תוכן דיגיטלי, ברשתות חברתיות אורגניות ובניהול קמפיינים ממומנים", "תיק עבודות חזק של סרטונים, גרפיקה ופוסטים שנוצרו אישית (חובה, ויכול להחליף השכלה פורמלית)", "יכולת צילום ועריכה מעשית ושליטה בכלים כמו Premiere Pro, CapCut או Canva", "היכרות עם Meta Ads, Google Ads, LinkedIn Campaign Manager, TikTok Ads ו-Google Analytics 4", "אנגלית חזקה בכתיבה ובתקשורת"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["מה גודל תקציב המדיה הממומנת ומי מאשר אותו?", "איזה ציוד ומשאבי הפקה עומדים לרשות התפקיד, והאם עובדים גם עם ספקים חיצוניים?", "איך מתבצע תהליך האישור של טענות קליניות ורגולטוריות בתוכן?"], "function": "שיווק", "regions": ["צפון"], "mode": "משרד", "car": "unknown", "minYears": 3, "level": "mid", "sector": "בריאות", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('globale-ppc-specialist', $j${"company": "Global-e", "role": "PPC Campaign Specialist", "location": "פתח תקווה (הפסגות 9), היברידי", "url": "https://www.comeet.com/jobs/global-e/62.002/ppc-campaign-specialist/AF.274", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פלטפורמה למסחר מקוון חוצה גבולות ישירות לצרכן, שמאפשרת למותגים ולקמעונאים למכור לכל העולם עם חוויה מקומית. הלקוחות הם מותגים וקמעונאים כגון Adidas, Hugo Boss ו-Logitech (לפי המודעה).", "about": "לפי המודעה: נסחרת בנאסד\"ק (GLBE) ופועלת בצפון אמריקה, ב-EMEA וב-APAC. התפקיד שייך לחטיבת ה-B2C, שמנהלת פעילות שיווק דיגיטלי עבור הסוחרים.", "requires": ["3 שנים ומעלה ניסיון מעשי בניהול קמפיינים PPC ב-Google וב-Facebook", "אנגלית ברמה גבוהה מאוד, רמת שפת אם, בכתב ובעל פה (חובה)", "יכולת בינאישית גבוהה ועבודה צמודה עם לקוחות", "יכולת אנליטית ושליטה מעמיקה ב-Excel", "יתרון: ניסיון בתחום האיקומרס או בסוכנות שיווק דיגיטלי"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["כמה סוחרים מנהל/ת כל מנהל/ת קמפיינים ומה היקף התקציבים?", "כמה ימים בשבוע עובדים מהמשרד בפתח תקווה?", "האם שעות העבודה מותאמות לאזורי הזמן של הלקוחות בחו\"ל?"], "function": "שיווק", "regions": ["מרכז"], "mode": "היברידי", "car": "unknown", "minYears": 3, "level": "mid", "sector": "תוכנה ואינטרנט", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('nayax-senior-field-marketing', $j${"company": "Nayax", "role": "Senior Field Marketing Manager", "location": "הרצליה (אריק איינשטיין 3, מטה החברה), היברידי", "url": "https://www.comeet.com/jobs/nayax/13.009/senior-field-marketing-manager/C4.476", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פתרונות תשלום ללא מזומן, מעורבות צרכנים וניהול עסק, בעיקר לנקודות מכירה אוטומטיות, שירות עצמי וקמעונאות. הלקוחות הם עסקים ומפעילים ביותר מ-120 מדינות.", "about": "לפי המודעה: נוסדה ב-2005, נסחרת בנאסד\"ק ובבורסה בתל אביב (NYAX), מעל 1,200 עובדים, והמטה העולמי נמצא בהרצליה ליד תחנת הרכבת.", "requires": ["5 שנים ומעלה ניסיון בשיווק B2B, רצוי בחברת טכנולוגיה גלובלית", "ניסיון מוכח בעבודה מול בעלי עניין מסחריים בכירים בשווקים גלובליים", "חשיבה אסטרטגית לצד ביצוע מעשי וניהול פרויקטים", "אנגלית ברמה מקצועית מלאה", "שימוש מעשי מתקדם ב-AI (סוכנים, תהליכי עבודה ואוטומציה) והיכרות עם CRM וכלי אוטומציה שיווקית"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["אילו קווי עסקים ושווקים כלולים באחריות התפקיד?", "האם התפקיד כולל ניהול עובדים או תקציב עצמאי? (במודעה ניהול צוות קטן מוגדר כיתרון)", "כמה נסיעות לחו\"ל ולאירועים צפויות בשנה?"], "function": "שיווק", "regions": ["שרון"], "mode": "היברידי", "car": "unknown", "minYears": 5, "level": "senior", "sector": "פיננסים ותשלומים", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('inmanage-qa-junior', $j${"company": "inManage", "role": "QA (בודק/ת תוכנה ידני/ת, רמת כניסה)", "location": "תל אביב-יפו (השפלה 3), עבודה מהמשרד", "url": "https://www.comeet.com/jobs/inmanage/B7.006/qa/C6.458", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "חברת פיתוח תוכנה שמתמחה בפתרונות איקומרס מתקדמים (אתרים ואפליקציות). לפי המודעה, בין הלקוחות מותגים גדולים כגון מקדונלד'ס, Grow, קרפור, ארומה ישראל ומחסני חשמל.", "about": "חברה פרטית ישראלית. גודל החברה ובעלותה לא צוינו במודעה. (מידע כללי, כדאי לאמת)", "requires": ["תעודת קורס QA או תואר אקדמי רלוונטי (חובה)", "0 עד 2 שנות ניסיון בבדיקות Web ומובייל (חובה)", "ניסיון בעבודה עם Jira", "רקע טכני חזק והיכרות עם מתודולוגיות בדיקה", "יתרון: ניסיון ב-SQL"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["כמה בודקים יש בצוות ומי מלווה בודק/ת חדש/ה?", "האם יש מסלול מעבר מבדיקות ידניות לאוטומציה?", "על כמה לקוחות ופרויקטים עובדים במקביל ומה קצב הגרסאות?"], "function": "QA ובדיקות", "regions": ["מרכז"], "mode": "משרד", "car": "unknown", "minYears": 0, "level": "junior", "sector": "תוכנה ואינטרנט", "english": "none", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('vastdata-graduate-qa-haifa', $j${"company": "VAST Data", "role": "Graduate QA Automation Engineer", "location": "חיפה (שדרות אבא חושי 199), עבודה מהמשרד", "url": "https://www.comeet.com/jobs/vastdata/43.001/graduate-qa-automation-engineer/8F.946", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פלטפורמת נתונים ותשתית תוכנה לעידן ה-AI: אחסון, קטלוג וניתוח של מאגרי נתונים עצומים לאימון והרצה של מודלים. הלקוחות הם ארגונים גדולים וספקי תשתיות AI.", "about": "חברה פרטית שהוקמה ב-2016 בידי יזמים ישראלים, עם מרכזי פיתוח בתל אביב ובחיפה ושווי של מיליארדי דולרים (מידע כללי, כדאי לאמת).", "requires": ["תואר B.Sc. או B.A. במדעי המחשב, הנדסה או תחום קרוב", "ניסיון ב-Python", "הבנה של מערכת ההפעלה Linux", "יתרון: ניסיון בפיתוח כלי בדיקה ואוטומציה", "יתרון: ניסיון בווירטואליזציה, ענן, רשתות או אחסון"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["המשרה מסומנת כרמת כניסה: האם היא מתאימה גם לבוגרים ללא ניסיון תעסוקתי כלל?", "מה היחס בין כתיבת קוד אוטומציה לבין הרצת בדיקות ידניות?", "איך נראית החניכה בחצי השנה הראשונה ומי המנטור/ית?"], "function": "QA ובדיקות", "regions": ["צפון"], "mode": "משרד", "car": "unknown", "minYears": 0, "level": "junior", "sector": "תוכנה ואינטרנט", "english": "none", "needsDegree": true, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('drivenets-qa-e2e', $j${"company": "DriveNets", "role": "QA E2E Engineer", "location": "רעננה (זרחין 1), היברידי", "url": "https://www.comeet.com/jobs/drivenets/72.006/qa-e2e-engineer/51.859", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פתרונות רשת בקנה מידה גדול לתשתיות AI ולספקיות תקשורת (Network Cloud ו-AI Fabric). הלקוחות הם מפעילות תקשורת כגון AT&T, Comcast ו-KDDI וכן חברות ענן ומעבדות AI (לפי המודעה).", "about": "לפי המודעה: נוסדה ב-2016, וביוני 2026 סגרה סבב D של 410 מיליון דולר שהביא את סך הגיוסים למיליארד דולר.", "requires": ["3 שנים לפחות בבדיקות אפליקציה (UI/UX, נתונים ותהליכים מרובי שלבים), כולל כתיבת STP/STD/STR", "ידע ברשתות ברמת CCNP ומעלה (L2/L3, BGP, VXLAN/EVPN)", "היכרות עם רשתות AI ועם אשכולות GPU (RoCE/RDMA, SLURM או Kubernetes)", "ניסיון מעשי חזק בסביבת Linux", "אנגלית ברמה גבוהה וניסיון מעשי בעבודה יומיומית עם סוכני AI (למשל Claude Code או Cursor)"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["כמה ימים בשבוע נדרשים במשרד ברעננה?", "אילו מהדרישות (רשתות, GPU, בדיקות אפליקציה) הן חובה מוחלטת ועל אילו אפשר ללמוד תוך כדי העבודה?", "מה החלוקה בין בדיקות ידניות, אוטומציה ותחזוקת סביבות הבדיקה?"], "function": "QA ובדיקות", "regions": ["שרון"], "mode": "היברידי", "car": "unknown", "minYears": 3, "level": "mid", "sector": "תקשורת", "english": "fluent", "needsDegree": false, "needsManagement": false}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('commit-automation-team-lead', $j${"company": "Commit", "role": "Automation Team Lead (ראש צוות QA אוטומציה)", "location": "פתח תקווה, עבודה מהמשרד", "url": "https://www.comeet.com/jobs/comm-it/76.008/automation-team-lead/50.F67", "applyHow": "מגישים מועמדות דרך טופס ההגשה שבעמוד המשרה (צירוף קורות חיים).", "sells": "פיתוח מוצרי תוכנה בהזמנה ללקוחות בתחומי Embedded, IoT, SaaS, AI, איקומרס, מובייל, בנקאות ו-Web. הלקוחות הם חברות וארגונים, כולל ארגוני אנטרפרייז ובנקים (לפי המודעה).", "about": "חברת שירותי פיתוח תוכנה ישראלית גדולה עם מאות עובדים (מידע כללי, כדאי לאמת).", "requires": ["7 שנים ומעלה ב-QA ובאוטומציית בדיקות", "3 שנים ומעלה כראש צוות או מנהל/ת QA, כולל ניהול אנשים בפועל", "מומחיות באוטומציה עם Playwright (חובה)", "שנה ומעלה עם כלי AI כגון Claude Code או Cursor, וניסיון מוכח ביישום AI בבדיקות", "אנגלית ברמה מקצועית והיכרות עם Git, JIRA ו-Jenkins"], "comp": "במודעה לא צוינו שכר או תנאים.", "ask": ["כמה בודקים בצוות ועבור איזה לקוח או מוצר עובדים?", "איזה חלק מהזמן מוקדש לעבודה מעשית על אוטומציה ואיזה לניהול?", "האם העבודה היא במשרדי החברה או באתר הלקוח, ומה היקף העבודה מול ארגונים פיננסיים?"], "function": "QA ובדיקות", "regions": ["מרכז"], "mode": "משרד", "car": "unknown", "minYears": 7, "level": "senior", "sector": "תוכנה ואינטרנט", "english": "good", "needsDegree": false, "needsManagement": true}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
-- Mark the first batch as sales jobs
update public.jobs set data = data || '{"function": "מכירות"}'::jsonb where not (data ? 'function');
